using System;
using System.Collections.Generic;
using BepInEx.Logging;
using Jotunn.Entities;
using Jotunn.Managers;
using Magenheim.Core;
using UnityEngine;
namespace Magenheim.Runtime;
internal sealed class DeepFractureCreatureRegistrar:IDisposable
{
 internal const string AnnoyanceWispPrefix="Magenheim_AnnoyanceWisp_",GeodeCrawlerPrefix="Magenheim_GeodeCrawler_",ShardlingPrefix="Magenheim_Shardling_",CrystalParasitePrefix="Magenheim_CrystalParasite_",CrystalRevenantPrefix="Magenheim_CrystalRevenant_",FacetSentryPrefix="Magenheim_FacetSentry_";
 private readonly ManualLogSource _log;private bool _subscribed,_registered;internal DeepFractureCreatureRegistrar(ManualLogSource log)=>_log=log??throw new ArgumentNullException(nameof(log));internal void Register(){if(_subscribed||_registered)return;PrefabManager.OnVanillaPrefabsAvailable+=RegisterContent;_subscribed=true;}
 private void RegisterContent(){if(_registered)return;try{var sources=new[]{RequireCreatureSource("Wisp"),RequireCreatureSource("Tick"),RequireCreatureSource("Greydwarf"),RequireCreatureSource("Leech"),RequireCreatureSource("Draugr"),RequireCreatureSource("DvergerMage")};var registered=new List<string>();foreach(ElementalAlignment a in Enum.GetValues(typeof(ElementalAlignment))){registered.Add(Register(sources[0],a,AnnoyanceWispPrefix,"Annoyance Wisp",34,5.5f,2.5f,DeepFractureCreatureVisuals.ApplyAnnoyanceWisp));registered.Add(Register(sources[1],a,GeodeCrawlerPrefix,"Geode Crawler",72,4,1.8f,DeepFractureCreatureVisuals.ApplyGeodeCrawler));registered.Add(Register(sources[2],a,ShardlingPrefix,"Shardling",48,6.2f,2.8f,DeepFractureCreatureVisuals.ApplyShardling));registered.Add(Register(sources[3],a,CrystalParasitePrefix,"Crystal Parasite",58,3.8f,1.6f,DeepFractureCreatureVisuals.ApplyCrystalParasite));registered.Add(Register(sources[4],a,CrystalRevenantPrefix,"Crystal Revenant",118,4.6f,2.1f,DeepFractureCreatureVisuals.ApplyCrystalRevenant));registered.Add(Register(sources[5],a,FacetSentryPrefix,"Facet Sentry",92,3.4f,1.4f,DeepFractureCreatureVisuals.ApplyFacetSentry));}_registered=true;_log.LogInfo($"Registered {registered.Count} additive Deep Fracture creature variants: {string.Join(", ",registered)}.");}catch(Exception e){_log.LogError($"Deep Fracture creature registration failed: {e}");throw;}finally{Dispose();}}
 private static GameObject RequireCreatureSource(string name){var s=PrefabManager.Instance.GetPrefab(name)??throw new InvalidOperationException($"Vanilla creature source '{name}' is unavailable; refusing to create an unverified chassis.");if(!s.GetComponent<Character>()||!s.GetComponent<BaseAI>()||!s.GetComponent<ZNetView>())throw new InvalidOperationException($"Vanilla creature source '{name}' lacks required Character/BaseAI/ZNetView behavior.");return s;}
 private static GameObject CloneVerified(string name,GameObject source){if(PrefabManager.Instance.GetPrefab(name))throw new InvalidOperationException($"Cannot replace occupied Deep Fracture creature identity '{name}'.");var p=PrefabManager.Instance.CreateClonedPrefab(name,source)??throw new InvalidOperationException($"Unable to clone Deep Fracture creature host '{name}'.");p.name=name;if(!p.GetComponent<Character>()||!p.GetComponent<BaseAI>()||!p.GetComponent<ZNetView>())throw new InvalidOperationException($"Cloned Deep Fracture creature '{name}' lost required behavior.");return p;}
 private static string Register(GameObject source,ElementalAlignment a,string prefix,string display,float hp,float run,float walk,Action<GameObject,ElementalAlignment> visuals){var name=prefix+a;var p=CloneVerified(name,source);var ch=p.GetComponent<Character>();ch.m_name=$"{a} {display}";ch.m_health=hp;ch.m_runSpeed=Mathf.Max(ch.m_runSpeed,run);ch.m_walkSpeed=Mathf.Max(ch.m_walkSpeed,walk);visuals(p,a);PrefabManager.Instance.AddPrefab(new CustomPrefab(p,true));return name;}
 public void Dispose(){if(!_subscribed)return;PrefabManager.OnVanillaPrefabsAvailable-=RegisterContent;_subscribed=false;}
}
